arguments.new_str:
/// <summary>
/// Filters and limits time parts to the requested precision, in-place.
/// </summary>
private static void SetPrecisionOfTimeSpan(
    List<string?> timeParts, int precision, bool countEmptyUnits)
{
    // Walk through the list, keeping up to `precision` items and removing the rest.
    int kept = 0;
    int writeIndex = 0;
    for (int i = 0; i < timeParts.Count; i++)
    {
        if (kept >= precision)
        {
            timeParts.RemoveRange(i, timeParts.Count - i);
            break;
        }

        bool isNonNull = timeParts[i] != null;

        if (countEmptyUnits)
        {
            kept++;
            if (isNonNull)
            {
                timeParts[writeIndex++] = timeParts[i];
            }
        }
        else
        {
            if (isNonNull)
            {
                timeParts[writeIndex++] = timeParts[i];
                kept++;
            }
        }
    }

    // Trim trailing entries beyond what we wrote
    if (writeIndex < timeParts.Count)
    {
        timeParts.RemoveRange(writeIndex, timeParts.Count - writeIndex);
    }
}

