/// Joins time part strings with the specified separator.
/// </summary>
private static string ConcatenateTimeSpanParts(
    List<string?> timeSpanParts, string collectionSeparator)
{
    // Count non-null parts and find last non-null index
    int nonNullCount = 0;
    int lastNonNullIndex = -1;
    for (int i = 0; i < timeSpanParts.Count; i++)
    {
        if (timeSpanParts[i] != null)
        {
            nonNullCount++;
            lastNonNullIndex = i;
        }
    }

    if (nonNullCount == 0)
    {
        return "no time";
    }

    if (nonNullCount == 1)
    {
        return timeSpanParts[lastNonNullIndex]!;
    }

    // Build "a, b and c" format without intermediate allocations
    var sb = new System.Text.StringBuilder();
    int written = 0;
    for (int i = 0; i < timeSpanParts.Count; i++)
    {
        if (timeSpanParts[i] == null) continue;

        if (written > 0)
        {
            sb.Append(written == nonNullCount - 1 ? " and " : collectionSeparator);
        }

        sb.Append(timeSpanParts[i]);
        written++;
    }

    return sb.ToString();
}

