private string HumanizeDisplayStrings(IEnumerable<string?> strings, string separator)
{
    // Single-pass: collect non-empty trimmed items into a list
    var items = new List<string>();
    foreach (var item in strings)
    {
        if (item == null) continue;
        var trimmed = item.AsSpan().Trim();
        if (trimmed.Length > 0)
        {
            // Avoid allocating a new string if Trim was a no-op
            items.Add(trimmed.Length == item.Length ? item : trimmed.ToString());
        }
    }

    if (items.Count == 0)
    {
        return string.Empty;
    }

    if (items.Count == 1)
    {
        return items[0];
    }

    var sb = new System.Text.StringBuilder();
    for (int i = 0; i < items.Count - 1; i++)
    {
        if (i > 0) sb.Append(separator);
        sb.Append(items[i]);
    }

    sb.Append(" and ").Append(items[^1]);
    return sb.ToString();
}

