    if (itemsArray.Length == 0)
    {
        return string.Empty;
    }

    if (itemsArray.Length == 1)
    {
        return itemsArray[0];
    }

    var allButLast = string.Join(separator, itemsArray.Take(itemsArray.Length - 1));
    return $"{allButLast} and {itemsArray[^1]}";
}

