34. {
35.     private const int DaysInAWeek = 7;
36.     private const double DaysInAYear = 365.2425;
37.     private const double DaysInAMonth = DaysInAYear / 12;
38. 
39.     private static readonly TimeUnit[] TimeUnits =
40.     [
41.         TimeUnit.Millisecond, TimeUnit.Second, TimeUnit.Minute, TimeUnit.Hour,
42.         TimeUnit.Day, TimeUnit.Week, TimeUnit.Month, TimeUnit.Year
43.     ];
44. 
45.     // Pre-computed lowercase unit names to avoid Enum.ToString() + ToLowerInvariant() per call
46.     private static readonly string[] UnitNames;
47.     private static readonly string[] UnitNamesPlural;
48. 
49.     static TimeSpanReadabilityExtensions()
50.     {
51.         var values = Enum.GetValues<TimeUnit>();
52.         UnitNames = new string[values.Length];
53.         UnitNamesPlural = new string[values.Length];
54.         foreach (var unit in values)
55.         {
56.             var name = unit.ToString().ToLowerInvariant();
57.             UnitNames[(int)unit] = name;
58.             UnitNamesPlural[(int)unit] = name + "s";
59.         }
60.     }
61. 
62.     /// <summary>
63.     /// Converts a <see cref="TimeSpan"/> to a human-readable string.
