69.     /// <param name="minUnit">The smallest time unit to display.</param>
70.     /// <param name="collectionSeparator">The separator between time parts (default: ", ").</param>
71.     /// <param name="countEmptyUnits">Whether empty units count toward precision.</param>
72.     /// <returns>A human-readable string representation of the time span.</returns>
73.     /// <example>
74.     /// <code>
